1	package relayproof
2	
3	// Regression coverage for how detection rules read the normalized action when
4	// one log supplies both action keys ("action" and its alias "event_type").
5	// Equality is judged only after JSON string decoding and after trimming
6	// surrounding Unicode whitespace from each side: different JSON spellings of
7	// the same character merge, while merely look-alike text stays distinct. The
8	// comparison is exact (case-sensitive, composition-sensitive) and interior
9	// characters are never trimmed. Every failing line is an isolated per-line
10	// ok:false record; text in unmapped fields is never subjected to the action
11	// trim or comparison rules.
12	
13	import (
14		"strings"
15		"testing"
16		"unicode/utf8"
17	)
18	
19	// Characters under test, built from code points so the source itself stays
20	// pure ASCII.
21	var (
22		grinningFace    = string(rune(0x1F600))      // 😀
23		eAcute          = string(rune(0x00E9))       // é: single precomposed rune
24		combiningEAcute = "e" + string(rune(0x0301)) // e followed by U+0301 combining acute
25		zeroWidthSpace  = string(rune(0x200B))       // zero-width space: content, never whitespace-trimmed
26	)
27	
28	// pairedEmojiToken is a JSON string literal spelling the grinning face via a
29	// legal surrogate-pair escape (rather than the literal astral character).
30	var pairedEmojiToken = "\"" + escGrinning + "\""
31	
32	const actionMergeTSLiteral = `"2026-01-02T00:00:00Z"`
33	
34	// dualActionLine places two already-complete JSON string tokens under the two
35	// action keys on one otherwise-valid log line.
36	func dualActionLine(actionToken, eventTypeToken string) string {
37		return `{"timestamp":` + actionMergeTSLiteral + `,"action":` + actionToken +
38			`,"event_type":` + eventTypeToken + `}`
39	}
40	
41	// dualActionOrderings returns every member ordering for a line that carries
42	// the timestamp plus both action keys, so canonical/alias position and input
43	// order are part of the asserted surface.
44	func dualActionOrderings(actionToken, eventTypeToken string) []string {
45		return dualOrderings(
46			kv{key: FieldAction, val: actionToken},
47			kv{key: "event_type", val: eventTypeToken},
48			kv{key: FieldTimestamp, val: actionMergeTSLiteral},
49		)
50	}
51	
52	// TestNormalizeActionEquivalentTextMerges pins the spellings that must denote
53	// one action: a literal astral character and its surrogate-pair escape decode
54	// to the same rune, and ordinary/no-break/ideographic spaces around the text
55	// are trimmed before comparison. The merged event keeps exactly one action
56	// (the trimmed full text), event_type never lands in extra, and rearranging
57	// members or swapping which spelling sits under which key is byte-invariant.
58	func TestNormalizeActionEquivalentTextMerges(t *testing.T) {
59		cases := []struct {
60			name        string
61			actionToken string
62			aliasToken  string
63			want        string
64		}{
65			{
66				name:        "emoji literal versus surrogate-pair escape",
67				actionToken: jsonString(grinningFace),
68				aliasToken:  pairedEmojiToken,
69				want:        grinningFace,
70			},
71			{
72				name:        "surrogate-pair escape versus emoji literal",
73				actionToken: pairedEmojiToken,
74				aliasToken:  jsonString(grinningFace),
75				want:        grinningFace,
76			},
77			{
78				name:        "ordinary spaces around one spelling",
79				actionToken: jsonString(" login "),
80				aliasToken:  jsonString("login"),
81				want:        "login",
82			},
83			{
84				name:        "ordinary spaces swapped to the other key",
85				actionToken: jsonString("login"),
86				aliasToken:  jsonString(" login "),
87				want:        "login",
88			},
89			{
90				name:        "no-break spaces around one spelling",
91				actionToken: jsonString(noBreakSpace + "login" + noBreakSpace),
92				aliasToken:  jsonString("login"),
93				want:        "login",
94			},
95			{
96				name:        "ideographic spaces around one spelling",
97				actionToken: jsonString(ideographicSpace + "login" + ideographicSpace),
98				aliasToken:  jsonString("login"),
99				want:        "login",
100			},
101			{
102				name:        "mixed special edges trimmed to the shared text",
103				actionToken: jsonString(noBreakSpace + "x" + ideographicSpace),
104				aliasToken:  jsonString(ideographicSpace + "x" + noBreakSpace),
105				want:        "x",
106			},
107			{
108				name:        "interior spaces survive trimming when both spellings match",
109				actionToken: jsonString("  log in  "),
110				aliasToken:  jsonString("log in"),
111				want:        "log in",
112			},
113		}
114		for _, tc := range cases {
115			t.Run(tc.name, func(t *testing.T) {
116				shared := assertOrderInvariant(t, dualActionOrderings(tc.actionToken, tc.aliasToken), true, nil)
117				event := eventOf(t, shared)
118				if got := event[FieldAction]; got != tc.want {
119					t.Fatalf("merged action = %q, want %q (event %#v)", got, tc.want, event)
120				}
121				if _, exists := event["extra"]; exists {
122					t.Fatalf("merged event_type must not reappear in extra: %#v", event)
123				}
124				if _, exists := event["event_type"]; exists {
125					t.Fatalf("only the canonical action key must survive: %#v", event)
126				}
127			})
128		}
129	}
130	
131	// TestNormalizeActionComparisonIsCaseSensitive: values differing only in case
132	// are different actions. Login/login must fail the whole line as a value
133	// conflict, in either key placement, never merge into one of the casings.
134	func TestNormalizeActionComparisonIsCaseSensitive(t *testing.T) {
135		for _, pair := range [][2]string{
136			{jsonString("Login"), jsonString("login")},
137			{jsonString("login"), jsonString("Login")},
138		} {
139			shared := assertOrderInvariant(
140				t, dualActionOrderings(pair[0], pair[1]), false,
141				[]string{FieldAction, "conflicting values", "Login", "login"},
142			)
143			if _, exists := shared["event"]; exists {
144				t.Fatalf("case conflict must not carry a partial event: %#v", shared)
145			}
146		}
147	}
148	
149	// TestNormalizeActionCompositionIsContent distinguishes canonical text from a
150	// look-alike decomposition. Precomposed é (U+00E9) and "e" + combining acute
151	// (U+0301) render almost identically but are different actions: together they
152	// conflict rather than merge, and the failure is a value conflict — never an
153	// illegal-character error. Supplied alone, each spelling is legal and must
154	// survive with its exact rune composition; normalization never rewrites one
155	// form into the other.
156	func TestNormalizeActionCompositionIsContent(t *testing.T) {
157		if eAcute == combiningEAcute {
158			t.Fatalf("test setup: the two spellings must be distinct strings")
159		}
160		if utf8.RuneCountInString(eAcute) != 1 || utf8.RuneCountInString(combiningEAcute) != 2 {
161			t.Fatalf("test setup: expected 1 vs 2 runes, got %d vs %d",
162				utf8.RuneCountInString(eAcute), utf8.RuneCountInString(combiningEAcute))
163		}
164	
165		t.Run("look-alike compositions conflict together", func(t *testing.T) {
166			for _, pair := range [][2]string{
167				{jsonString(eAcute), jsonString(combiningEAcute)},
168				{jsonString(combiningEAcute), jsonString(eAcute)},
169			} {
170				shared := assertOrderInvariant(
171					t, dualActionOrderings(pair[0], pair[1]), false,
172					[]string{FieldAction, "conflicting values"},
173				)
174				msg, _ := shared["error"].(string)
175				for _, bad := range []string{"invalid UTF-8", "surrogate", "illegal", "invalid character"} {
176					if strings.Contains(msg, bad) {
177						t.Fatalf("two legal spellings must not be reported as %q: %q", bad, msg)
178					}
179				}
180			}
181		})
182	
183		t.Run("each spelling alone keeps its rune composition", func(t *testing.T) {
184			alone := []struct {
185				name  string
186				input string
187				want  string
188			}{
189				{"precomposed under canonical key",
190					`{"timestamp":` + actionMergeTSLiteral + `,"action":` + jsonString(eAcute) + `}`, eAcute},
191				{"precomposed under alias key",
192					`{"timestamp":` + actionMergeTSLiteral + `,"event_type":` + jsonString(eAcute) + `}`, eAcute},
193				{"decomposed under canonical key",
194					`{"timestamp":` + actionMergeTSLiteral + `,"action":` + jsonString(combiningEAcute) + `}`, combiningEAcute},
195				{"decomposed under alias key",
196					`{"timestamp":` + actionMergeTSLiteral + `,"event_type":` + jsonString(combiningEAcute) + `}`, combiningEAcute},
197			}
198			for _, tc := range alone {
199				t.Run(tc.name, func(t *testing.T) {
200					results := runNormalize(t, tc.input)
201					if results[0]["ok"] != true {
202						t.Fatalf("legal spelling must succeed on its own: %#v", results[0])
203					}
204					got := eventOf(t, results[0])[FieldAction].(string)
205					if got != tc.want {
206						t.Fatalf("action composition rewritten: got %q want %q", got, tc.want)
207					}
208					if got == eAcute && tc.want == combiningEAcute || got == combiningEAcute && tc.want == eAcute {
209						t.Fatalf("output must not cross the two compositions: got %q want %q", got, tc.want)
210					}
211				})
212			}
213		})
214	}
215	
216	// TestNormalizeActionInteriorCharactersAreContent: trimming applies only at
217	// the edges. Spaces (and zero-width spaces) in the middle are part of the
218	// action and are not deleted before comparison. A zero-width space at an edge
219	// is likewise content — Unicode whitespace trimming does not remove it — so it
220	// conflicts with the alias lacking it, while matching ZWSP-bearing spellings
221	// merge with the ZWSP retained.
222	func TestNormalizeActionInteriorCharactersAreContent(t *testing.T) {
223		conflicts := []struct {
224			name string
225			a, b string
226		}{
227			{"interior space versus no space", jsonString("log in"), jsonString("login")},
228			{"interior zero-width space versus none", jsonString("log" + zeroWidthSpace + "in"), jsonString("login")},
229			{"leading zero-width space not trimmed", jsonString(zeroWidthSpace + "login"), jsonString("login")},
230			{"trailing zero-width space not trimmed", jsonString("login" + zeroWidthSpace), jsonString("login")},
231		}
232		for _, tc := range conflicts {
233			t.Run(tc.name, func(t *testing.T) {
234				shared := assertOrderInvariant(
235					t, dualActionOrderings(tc.a, tc.b), false,
236					[]string{FieldAction, "conflicting values"},
237				)
238				if _, exists := shared["event"]; exists {
239					t.Fatalf("content-distinct actions must not emit an event: %#v", shared)
240				}
241			})
242		}
243	
244		t.Run("matching zero-width space survives a merge", func(t *testing.T) {
245			want := zeroWidthSpace + "login"
246			shared := assertOrderInvariant(
247				t, dualActionOrderings(jsonString(want), jsonString(" "+want+" ")), true, nil,
248			)
249			if got := eventOf(t, shared)[FieldAction]; got != want {
250				t.Fatalf("zero-width space is content and must survive, got %q want %q", got, want)
251			}
252		})
253	
254		t.Run("a zero-width-space-only action is legal non-empty text", func(t *testing.T) {
255			for _, key := range []string{FieldAction, "event_type"} {
256				input := `{"timestamp":` + actionMergeTSLiteral + `,"` + key + `":` + jsonString(zeroWidthSpace) + `}`
257				results := runNormalize(t, input)
258				if results[0]["ok"] != true {
259					t.Fatalf("ZWSP-only action must be a valid non-empty action: %#v", results[0])
260				}
261				got := eventOf(t, results[0])[FieldAction].(string)
262				if got != zeroWidthSpace || utf8.RuneCountInString(got) != 1 {
263					t.Fatalf("ZWSP-only action must round-trip as one rune, got %q", got)
264				}
265			}
266		})
267	}
268	
269	// TestNormalizeActionEmptyAfterTrimFailsWholeLine: if either action field is
270	// empty once its surrounding whitespace is removed, the whole line fails as
271	// an empty action — even when the other field carries a legal value. It is
272	// never dropped to let the legal side win, and it is not demoted to a missing
273	// field or reported as a conflict.
274	func TestNormalizeActionEmptyAfterTrimFailsWholeLine(t *testing.T) {
275		empties := []string{
276			jsonString(""),
277			jsonString("   "),
278			jsonString("\t\n "),
279			jsonString(noBreakSpace),
280			jsonString(ideographicSpace),
281			jsonString(noBreakSpace + ideographicSpace + " "),
282		}
283		for _, empty := range empties {
284			for _, pair := range [][2]string{
285				{empty, jsonString("login")},
286				{jsonString("login"), empty},
287			} {
288				shared := assertOrderInvariant(
289					t, dualActionOrderings(pair[0], pair[1]), false,
290					[]string{FieldAction, "action must not be empty"},
291				)
292				msg, _ := shared["error"].(string)
293				if strings.Contains(msg, "conflict") {
294					t.Fatalf("an empty action is an empty-value error, not a conflict: %q", msg)
295				}
296			}
297		}
298	
299		t.Run("whitespace-only alias provided alone fails as empty, not missing", func(t *testing.T) {
300			input := `{"timestamp":` + actionMergeTSLiteral + `,"event_type":` + jsonString("   ") + `}`
301			results := runNormalize(t, input)
302			if results[0]["ok"] != false {
303				t.Fatalf("whitespace-only event_type must fail: %#v", results[0])
304			}
305			msg, _ := results[0]["error"].(string)
306			if !strings.Contains(msg, FieldAction) || !strings.Contains(msg, "action must not be empty") {
307				t.Fatalf("failure must name an empty %q, got %q", FieldAction, msg)
308			}
309			if strings.Contains(msg, "missing") {
310				t.Fatalf("a provided empty alias must not be treated as an omission: %q", msg)
311			}
312		})
313	}
314	
315	// TestNormalizeActionFailuresAreIsolatedInStream drives several action
316	// problems through one batch interleaved with valid logs and a blank line.
317	// Each bad record fails alone with its original physical line number and a
318	// specific reason; the legal logs before and after still process in order, and
319	// the failure count equals the number of failing records.
320	func TestNormalizeActionFailuresAreIsolatedInStream(t *testing.T) {
321		input := strings.Join([]string{
322			`{"timestamp":` + actionMergeTSLiteral + `,"action":"first"}`,
323			"", // blank: advances the physical line counter, emits nothing
324			dualActionLine(jsonString("Login"), jsonString("login")),
325			dualActionLine(jsonString("   "), jsonString("login")),
326			dualActionLine(jsonString(eAcute), jsonString(combiningEAcute)),
327			dualActionLine(jsonString(zeroWidthSpace+"go"), jsonString("go")),
328			`{"timestamp":` + actionMergeTSLiteral + `,"action":"last"}`,
329		}, "\n")
330	
331		results := runNormalize(t, input) // also asserts emitted failures == returned count
332		if len(results) != 6 {
333			t.Fatalf("expected 6 records for 7 physical lines (one blank), got %d: %#v", len(results), results)
334		}
335	
336		if results[0]["line"] != float64(1) || results[0]["ok"] != true {
337			t.Fatalf("line 1 must succeed: %#v", results[0])
338		}
339		if eventOf(t, results[0])[FieldAction] != "first" {
340			t.Fatalf("line 1 action must survive in order: %#v", results[0])
341		}
342	
343		type expect struct {
344			line   float64
345			substr string
346			forbid string
347		}
348		wants := []expect{
349			{3, "conflicting values", ""}, // case difference
350			{4, "action must not be empty", "conflict"},
351			{5, "conflicting values", "invalid"}, // look-alike composition, not an illegal character
352			{6, "conflicting values", ""},        // edge zero-width space
353		}
354		for i, w := range wants {
355			r := results[i+1]
356			if r["line"] != w.line || r["ok"] != false {
357				t.Fatalf("record %d must be a failure on physical line %v: %#v", i+1, w.line, r)
358			}
359			if _, exists := r["event"]; exists {
360				t.Fatalf("line %v failure must not carry a partial event: %#v", w.line, r)
361			}
362			msg, _ := r["error"].(string)
363			if !strings.Contains(msg, FieldAction) || !strings.Contains(msg, w.substr) {
364				t.Fatalf("line %v error must name %q and contain %q, got %q", w.line, FieldAction, w.substr, msg)
365			}
366			if w.forbid != "" && strings.Contains(msg, w.forbid) {
367				t.Fatalf("line %v error must not mention %q: %q", w.line, w.forbid, msg)
368			}
369		}
370	
371		last := results[5]
372		if last["line"] != float64(7) || last["ok"] != true {
373			t.Fatalf("legal line 7 must still be processed after the failures: %#v", last)
374		}
375		if eventOf(t, last)[FieldAction] != "last" {
376			t.Fatalf("line 7 action must survive in input order: %#v", last)
377		}
378	}
379	
380	// TestNormalizeUnknownFieldTextSkipsActionRules: look-alike text living in an
381	// unmapped field (a plain unknown key or the input's own extra) is preserved
382	// verbatim under the existing extra rules. It is never trimmed like an action
383	// or compared against the action, and the merged event_type does not appear
384	// there.
385	func TestNormalizeUnknownFieldTextSkipsActionRules(t *testing.T) {
386		note := zeroWidthSpace + "login"
387		label := noBreakSpace + "x" + ideographicSpace
388		raw := "  " + zeroWidthSpace + " "
389		input := `{"timestamp":` + actionMergeTSLiteral +
390			`,"action":` + jsonString(" login ") +
391			`,"event_type":` + jsonString("login") +
392			`,"note":` + jsonString(note) +
393			`,"label":` + jsonString(label) +
394			`,"extra":{"raw":` + jsonString(raw) + `}}`
395	
396		results := runNormalize(t, input)
397		if results[0]["ok"] != true {
398			t.Fatalf("unknown-field text must not disturb a valid merge: %#v", results[0])
399		}
400		event := eventOf(t, results[0])
401		if event[FieldAction] != "login" {
402			t.Fatalf("action must merge and trim to %q, got %q", "login", event[FieldAction])
403		}
404		if _, exists := event["event_type"]; exists {
405			t.Fatalf("merged alias must not be copied into the event: %#v", event)
406		}
407		extra := extraOf(t, results[0])
408		if extra["note"] != note {
409			t.Fatalf("edge zero-width space in unknown text must be preserved, got %q", extra["note"])
410		}
411		if extra["label"] != label {
412			t.Fatalf("special edge spaces in unknown text must be preserved, got %q", extra["label"])
413		}
414		inner, ok := extra["extra"].(map[string]any)
415		if !ok {
416			t.Fatalf("input extra must stay a nested unknown field: %#v", extra["extra"])
417		}
418		if inner["raw"] != raw {
419			t.Fatalf("whitespace/ZWSP-only unknown text must be kept verbatim, got %q", inner["raw"])
420		}
421	}
